const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));
const today = new Date().toLocaleDateString('en-CA');
const open = (queries.records.data || []).filter(x => x.status !== 'Resolved').sort((a, b) => String(a.due || '').localeCompare(String(b.due || '')));
const next = open.find(x => x.id === variables.previewId) || open[0];
return {
  openCount: open.length,
  pastCount: open.filter(x => x.due < today).length,
  rows: open.slice(0, 4).map(x => ({ id: x.id, first: !!next && x.id === next.id, customer: x.customer, past: x.due < today, tag: x.due < today ? 'Past target' : x.priority, name: x.name, meta: x.reference + ' · ' + x.owner + ' · ' + x.status })),
  next: next ? { id: next.id, name: next.name, sub: next.customer + ' · ' + next.reference, owner: next.owner, queue: next.queue, description: next.description, messages: (next.messages || []).slice(-2).map(m => ({ meta: m.author + ' · ' + m.kind, body: esc(m.body) })) } : null
};

const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));
const date = d => d ? new Date(d + 'T12:00:00').toLocaleDateString('en-US', {month: 'short', day: 'numeric', year: 'numeric'}) : 'Not scheduled';
const r = (queries.records.data || []).find(x => x.id === variables.recordId);
return r ? {
  reference: r.reference, queue: String(r.queue || '').toUpperCase(), name: r.name,
  meta: r.customer + ' · Assigned to ' + r.owner + ' · ' + r.priority + ' priority · Target ' + date(r.due),
  description: r.description, status: r.status,
  messages: (r.messages || []).map(m => ({ meta: m.author + ' · ' + m.kind, body: esc(m.body) })),
  history: (r.history || []).slice().reverse()
} : null;
